/*
 * Ported from samasante/liquid-glass (src/GlassMaterial.tsx), at commit 4e7b769e1df7:
 * https://github.com/samasante/liquid-glass. Comments that named a vendor's
 * design language were reworded; the code is upstream's unless a "Port:"
