"use client";

import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import {
  type GlassLensParams,
  type GlassOptics,
  DEFAULT_LENS_PARAMS,
  createLensMapGenerator,
  type LensMapGenerator,
} from "./glass-displacement";
import { type GlassValue, isGlassMotionValue, readGlassValue } from "./glass-signal";
import { GlassWebGLRenderer, type GlassLensDescriptor } from "./glass-webgl";

/*
 * Ported from samasante/liquid-glass (src/GlassSurface.tsx), at commit 4e7b769e1df7:
 * https://github.com/samasante/liquid-glass. Comments that named a vendor's
 * design language were reworded; the code is upstream's unless a "Port:"
 * comment says otherwise.
